#!/usr/bin/env python3
"""Independent, deliberately naive reference implementation (dev only)."""
import json, sys, re
from fractions import Fraction

def bad():
    raise ValueError("invalid")

def isint(v):
    return type(v) is int

def keys(o, ks):
    if type(o) is not dict: bad()
    if set(o.keys()) != set(ks): bad()

def iv(v, lo, hi):
    if not isint(v) or v < lo or v > hi: bad()
    return v

def load(text):
    def pairs(ps):
        d = {}
        for k, v in ps:
            if k in d: bad()
            d[k] = v
        return d
    def fl(s): bad()
    def co(s): bad()
    return json.loads(text, object_pairs_hook=pairs, parse_float=fl, parse_constant=co)

def run(text):
    doc = load(text)
    keys(doc, ["version","config","model","connections","packets"])
    if doc["version"] != 1 or not isint(doc["version"]): bad()
    cfg = doc["config"]; mdl = doc["model"]
    keys(cfg, ["slots","window","idle_timeout","len_quantum","gap_quantum","rate_num","rate_den","bucket_capacity","initial_tokens","pending_capacity","lanes","service","fallback","time_edges","count_edges","probability"])
    keys(mdl, ["classes","embedding_dim","length_embedding","gap_embedding","kernel","conv_weights","conv_bias","conv_shift","dense_weights","dense_bias"])

    C = iv(mdl["classes"],2,8)
    E = iv(mdl["embedding_dim"],1,4)
    def mat(v, r, c, lo, hi):
        if type(v) is not list or len(v) != r: bad()
        for row in v:
            if type(row) is not list or len(row) != c: bad()
            for x in row: iv(x, lo, hi)
        return v
    LE = mat(mdl["length_embedding"],16,E,-128,127)
    GE = mat(mdl["gap_embedding"],16,E,-128,127)
    K = iv(mdl["kernel"],1,5)
    CW = mdl["conv_weights"]
    if type(CW) is not list: bad()
    F = len(CW)
    if not (1 <= F <= 8): bad()
    for row in CW: mat(row,K,2*E,-128,127)
    def vec(v,n,lo,hi):
        if type(v) is not list or len(v) != n: bad()
        for x in v: iv(x,lo,hi)
        return v
    CB = vec(mdl["conv_bias"],F,-2**31,2**31-1)
    CS = vec(mdl["conv_shift"],F,0,16)
    DW = mat(mdl["dense_weights"],C,F,-128,127)
    DB = vec(mdl["dense_bias"],C,-2**31,2**31-1)

    S = iv(cfg["slots"],1,256)
    W = iv(cfg["window"],1,16)
    if K > W: bad()
    IDLE = iv(cfg["idle_timeout"],1,10**12)
    LQ = iv(cfg["len_quantum"],1,65535)
    GQ = iv(cfg["gap_quantum"],1,65535)
    RN = iv(cfg["rate_num"],1,10**6)
    RD = iv(cfg["rate_den"],1,10**6)
    CAP = iv(cfg["bucket_capacity"],1,512)
    INIT = iv(cfg["initial_tokens"],0,CAP)
    PC = iv(cfg["pending_capacity"],1,512)
    L = iv(cfg["lanes"],1,4)
    SVC = vec(cfg["service"],C,1,10**6)
    FB = iv(cfg["fallback"],0,C-1)
    def edges(v, lo, hi):
        if type(v) is not list or not (1 <= len(v) <= 16): bad()
        for x in v: iv(x, lo, hi)
        for i in range(1,len(v)):
            if v[i] <= v[i-1]: bad()
        if v[0] != 0: bad()
        return v
    TE = edges(cfg["time_edges"],0,10**12)
    CE = edges(cfg["count_edges"],0,20000)
    P = cfg["probability"]
    if type(P) is not list or len(P) != len(TE): bad()
    for row in P: vec(row,len(CE),0,65536)

    conns = doc["connections"]
    if type(conns) is not list or len(conns) > 2048: bad()
    ids = []
    info = {}
    for c in conns:
        keys(c, ["id","slot","label","split"])
        i = c["id"]
        if type(i) is not str or re.fullmatch(r"[A-Za-z0-9_-]{1,32}", i) is None: bad()
        if i in info: bad()
        iv(c["slot"],0,S-1)
        iv(c["label"],0,C-1)
        if c["split"] not in ("dev","eval") or type(c["split"]) is not str: bad()
        info[i] = {"slot": c["slot"], "label": c["label"], "split": c["split"],
                   "packets": 0, "votes": [0]*C}
        ids.append(i)

    pkts = doc["packets"]
    if type(pkts) is not list or len(pkts) > 20000: bad()
    prev = None
    pl = []
    for p in pkts:
        keys(p, ["time","connection","length","draw"])
        t = iv(p["time"],0,10**12)
        if prev is not None and t < prev: bad()
        prev = t
        if type(p["connection"]) is not str or p["connection"] not in info: bad()
        iv(p["length"],0,65535)
        iv(p["draw"],0,65535)
        pl.append((t,p["connection"],p["length"],p["draw"]))

    # ---------------- replay ----------------
    slots = [None]*S       # each: dict conn,gen,window,cached,last_applied,anchor,backlog,last_time
    gens = [0]*S
    lanes = [0]*L
    credit = INIT*RD
    lastref = 0
    jobs = []
    pending = []   # list of job dicts

    def rdiv(z, s):
        if s == 0: return z
        d = 2**s
        if z >= 0:
            return (2*z + d)//(2*d)
        return -((2*(-z) + d)//(2*d))

    def cnn(win):
        x = [LE[a] + GE[b] for (a,b) in win]
        pooled = []
        for f in range(F):
            vals = []
            for j in range(W-K+1):
                z = CB[f]
                for k in range(K):
                    for d in range(2*E):
                        z += CW[f][k][d]*x[j+k][d]
                z = rdiv(z, CS[f])
                if z < 0: z = 0
                if z > 127: z = 127
                vals.append(z)
            pooled.append(max(vals))
        logits = []
        for c in range(C):
            s = DB[c]
            for f in range(F):
                s += DW[c][f]*pooled[f]
            logits.append(s)
        m = max(logits)
        pred = logits.index(m)
        return logits, pred

    def finish_all(limit):
        # finish jobs with done <= limit (or all if limit is None) in (done,id) order
        while True:
            cand = [j for j in pending if limit is None or j["done"] <= limit]
            if not cand: break
            cand.sort(key=lambda j: (j["done"], j["id"]))
            j = cand[0]
            pending.remove(j)
            st = slots[j["slot"]]
            if st is None or st["conn"] != j["connection"] or st["gen"] != j["generation"]:
                j["status"] = "stale"
            elif j["id"] <= st["last_applied"]:
                j["status"] = "superseded"
            else:
                j["status"] = "applied"
                st["cached"] = j["prediction"]
                st["last_applied"] = j["id"]

    outp = []
    for idx,(t,cid,length,draw) in enumerate(pl):
        finish_all(t)
        credit = min(CAP*RD, credit + (t-lastref)*RN)
        lastref = t
        si = info[cid]["slot"]
        st = slots[si]
        if st is None or st["conn"] != cid or t - st["last_time"] >= IDLE:
            gens[si] += 1
            st = {"conn":cid,"gen":gens[si],"window":[],"cached":None,"last_applied":-1,
                  "anchor":t,"backlog":0,"last_time":t}
            slots[si] = st
            gap = 0
        else:
            gap = t - st["last_time"]
            st["last_time"] = t
        a = min(15, length//LQ)
        b = min(15, gap//GQ)
        st["window"].append([a,b])
        if len(st["window"]) > W:
            st["window"] = st["window"][-W:]
        st["backlog"] += 1
        fwd = st["cached"] if st["cached"] is not None else FB
        info[cid]["votes"][fwd] += 1
        info[cid]["packets"] += 1
        # bins
        ti = 0
        for i in range(len(TE)):
            if TE[i] <= t - st["anchor"]: ti = i
        ci = 0
        for i in range(len(CE)):
            if CE[i] <= st["backlog"]: ci = i
        p = P[ti][ci]
        jid = None
        if len(st["window"]) < W:
            dec = "warmup"
        elif draw >= p:
            dec = "probability"
        elif credit < RD:
            dec = "tokens"
        elif len(pending) >= PC:
            dec = "queue"
        else:
            dec = "sent"
            credit -= RD
            wincopy = [list(r) for r in st["window"]]
            logits, pred = cnn(wincopy)
            jid = len(jobs)
            order = sorted(range(L), key=lambda l: (lanes[l], l))
            lane = order[0]
            start = max(t, lanes[lane])
            done = start + SVC[pred]
            lanes[lane] = done
            job = {"id":jid,"packet":idx,"connection":cid,"slot":si,"generation":st["gen"],
                   "lane":lane,"start":start,"done":done,"window":wincopy,"logits":logits,
                   "prediction":pred,"status":None}
            jobs.append(job)
            pending.append(job)
            st["anchor"] = t
            st["backlog"] = 0
        outp.append({"index":idx,"connection":cid,"generation":st["gen"],"forward":fwd,
                     "decision":dec,"credit":credit,"job":jid})
    finish_all(None)

    outc = []
    for cid in ids:
        d = info[cid]
        v = d["votes"]
        pred = None
        if d["packets"] > 0:
            m = max(v)
            pred = v.index(m)
        outc.append({"id":cid,"split":d["split"],"label":d["label"],"packets":d["packets"],
                     "votes":v,"prediction":pred})
    reps = {}
    for split in ("dev","eval"):
        conf = [[0]*C for _ in range(C)]
        n = 0
        for e in outc:
            if e["split"] != split or e["packets"] == 0: continue
            n += 1
            conf[e["label"]][e["prediction"]] += 1
        tot = Fraction(0)
        for c in range(C):
            tp = conf[c][c]
            fp = sum(conf[r][c] for r in range(C)) - tp
            fn = sum(conf[c]) - tp
            den = 2*tp+fp+fn
            if den > 0:
                tot += Fraction(2*tp, den)
        f = tot / C
        reps[split] = {"connections":n,"confusion":conf,"macro_f1":[f.numerator,f.denominator]}
    return {"packets":outp,"jobs":jobs,"connections":outc,"reports":reps}

if __name__ == "__main__":
    text = sys.stdin.buffer.read().decode("utf-8")
    try:
        r = run(text)
    except Exception:
        sys.stdout.write('{"error":"invalid-input"}')
        sys.exit(0)
    sys.stdout.write(json.dumps(r, separators=(",",":")))
